import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ProductService } from '../../services/product.service';
import { CartService } from '../../services/cart.service';
import { AuthService } from '../../services/auth.service';
import { Product } from '../../models/product';

@Component({
  selector: 'app-product-details',
  templateUrl: './product-details.component.html',
  styleUrls: ['./product-details.component.css']
})
export class ProductDetailsComponent implements OnInit {
  product: Product | undefined;
  quantity = 1;
  added = false;

  constructor(
    private route: ActivatedRoute,
    private productService: ProductService,
    public cart: CartService,
    public auth: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    const id = Number(this.route.snapshot.paramMap.get('id'));
    this.productService.getProduct(id).subscribe(p => this.product = p);
  }

  addToCart(): void {
    if (!this.auth.isLoggedIn) { this.router.navigate(['/login']); return; }
    if (!this.product) return;
    for (let i = 0; i < this.quantity; i++) {
      this.cart.addToCart(this.product);
    }
    this.added = true;
    setTimeout(() => this.added = false, 2000);
  }

  goBack(): void { this.router.navigate(['/products']); }
}
<div class="details-page" *ngIf="product; else loading">
  <button class="back-btn" (click)="goBack()">← Back to Products</button>

  <div class="details-card">
    <div class="details-img-section">
      <img [src]="product.imageUrl" [alt]="product.name" class="details-img" />
      <span class="details-category">{{ product.category }}</span>
    </div>

    <div class="details-info">
      <h1 class="details-name">{{ product.name }}</h1>
      <p class="details-desc">{{ product.description }}</p>

      <div class="details-price-row">
        <span class="details-price">₹{{ product.price | number }}</span>
        <span class="stock-info" [class.out]="product.stock === 0">
          {{ product.stock > 0 ? product.stock + ' in stock' : 'Out of Stock' }}
        </span>
      </div>

      <div class="quantity-row" *ngIf="product.stock > 0">
        <label>Quantity:</label>
        <div class="qty-controls">
          <button (click)="quantity = quantity > 1 ? quantity - 1 : 1">−</button>
          <span>{{ quantity }}</span>
          <button (click)="quantity = quantity < product.stock ? quantity + 1 : quantity">+</button>
        </div>
      </div>

      <button
        class="add-btn"
        [class.added]="added"
        (click)="addToCart()"
        [disabled]="product.stock === 0"
      >
        {{ added ? '✓ Added to Cart!' : '🛒 Add to Cart' }}
      </button>

      <div class="details-meta">
        <div><strong>Category:</strong> {{ product.category }}</div>
        <div><strong>SKU:</strong> PROD-{{ product.id | number:'4.0-0' }}</div>
      </div>
    </div>
  </div>
</div>

<ng-template #loading>
  <div class="loading-state">
    <div class="spinner"></div>
    <p>Loading product...</p>
  </div>
</ng-template>
